using System;
using Unity.Collections;

namespace UnityEngine.Rendering.HighDefinition
{
    internal static class HDShadowLightIndexResolver
    {
        private const int AMBIGUOUS_LIGHT_INDEX = -1;

        internal static void BuildMap(NativeArray<int> visibleLightEntityIndices, int visibleLightCount, ref NativeHashMap<int, int> map)
        {
            map.Clear();
            if (map.Capacity < visibleLightCount)
            {
                map.Capacity = visibleLightCount;
            }
            for (int index = 0; index < visibleLightCount; index++)
            {
                int dataIndex = visibleLightEntityIndices[index];
                if (dataIndex >= 0 && !map.TryAdd(dataIndex, index))
                {
                    map[dataIndex] = AMBIGUOUS_LIGHT_INDEX;
                }
            }
        }

        internal static int Resolve(int dataIndex, int requestLightIndex, int mappedLightIndex, NativeArray<int> visibleLightEntityIndices, int visibleLightCount)
        {
            if (mappedLightIndex >= 0)
            {
                return mappedLightIndex;
            }
            if (mappedLightIndex != AMBIGUOUS_LIGHT_INDEX || requestLightIndex < 0 || requestLightIndex >= visibleLightCount || requestLightIndex >= visibleLightEntityIndices.Length || visibleLightEntityIndices[requestLightIndex] != dataIndex)
            {
                throw new InvalidOperationException("Ambiguous shadow light mapping has no matching original native light index. Entity data index: " + dataIndex + "; request light index: " + requestLightIndex + ".");
            }
            return requestLightIndex;
        }
    }

    [Serializable]
    public struct HDShadowRequestObservation
    {
        public int frame;
        public int renderedFrame;
        public double realtime;
        public string cameraId;
        public string passName;
        public int requestDataIndex;
        public int requestLightIndex;
        public int mappedLightIndex;
        public int cullingLightCount;
        public string cullingLightInstanceId;
        public string expectedLightInstanceId;
        public int splitIndex;
        public int shadowMapType;
        public int requestSetIndex;
        public int packedSetIndex;
        public int expectedDataIndex;
        public int expectedVisibleLightIndex;
        public int currentDataEntityIndex;
        public string currentDataLightInstanceId;
        public bool mapFound;
        public bool ownerSetMatches;
        public bool mappedLightEnabled;
        public int mappedLightShadows;
        public float mappedLightShadowStrength;
        public float mappedLightRange;
        public float mappedLightIntensity;
        public float culledRange;
        public float culledColorR;
        public float culledColorG;
        public float culledColorB;
        public bool isInCachedAtlas;
        public bool shouldUseCachedShadowData;
        public bool shouldRenderCachedComponent;
        public bool isRenderingOnCache;
        public bool willCreateRendererList;
        public bool cullingSnapshotFound;
        public bool cullingResultsMatch;
        public int cullingSequence;
        public int cullingCapturedFrame;
        public int cullingSnapshotLightCount;
        public int cullingSnapshotInfoCount;
        public int cullingTotalSplitCount;
        public int originalSplitStart;
        public int originalSplitCount;
        public int originalSplitExclusionMask;
        public int originalProjectionType;
        public int mappedSplitStart;
        public int mappedSplitCount;
        public int mappedSplitExclusionMask;
        public int mappedProjectionType;
        public bool originalSplitExcluded;
        public bool mappedSplitExcluded;
        public bool originalSplitInBuffer;
        public bool mappedSplitInBuffer;
        public int duplicateVisibleLightCount;
        public string originalLightInstanceId;
        public float originalPositionX;
        public float originalPositionY;
        public float originalPositionZ;
        public float mappedPositionX;
        public float mappedPositionY;
        public float mappedPositionZ;
    }

    public static class HDShadowRequestDiagnostics
    {
        private const int MAX_OBSERVATIONS_PER_FRAME = 2048;
        private const int MAX_CULLING_CAMERAS = 8;
        private const int MAX_CULLING_LIGHTS = 1024;

        private static int _frame = -1;
        private static int _count;
        private static int _cullingSequence;
        private static int _nextCullingSlot;
        private static CullingSnapshot[] _cullingSnapshots;

        public static bool Enabled { get; set; }
        public static int DroppedObservations { get; private set; }

        internal static string CameraInstanceId { get; set; }

        public static event Action<HDShadowRequestObservation> Observed;

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
        private static void Reset()
        {
            Enabled = false;
            CameraInstanceId = null;
            DroppedObservations = 0;
            _frame = -1;
            _count = 0;
            _cullingSequence = 0;
            _nextCullingSlot = 0;
            _cullingSnapshots = null;
            Observed = null;
        }

        private sealed class CullingSnapshot
        {
            public string CameraId { get; set; }
            public int Frame { get; set; }
            public int Sequence { get; set; }
            public int LightCount { get; set; }
            public int InfoCount { get; set; }
            public int TotalSplitCount { get; set; }
            public CullingResults Results { get; set; }
            public LightShadowCasterCullingInfo[] PerLightInfos { get; } = new LightShadowCasterCullingInfo[MAX_CULLING_LIGHTS];
        }

        internal static void CaptureCulling(string cameraId, CullingResults cullingResults, NativeArray<LightShadowCasterCullingInfo> perLightInfos, int totalSplitCount)
        {
            if (!Enabled || Observed == null)
            {
                return;
            }
            if (_cullingSnapshots == null)
            {
                _cullingSnapshots = new CullingSnapshot[MAX_CULLING_CAMERAS];
            }
            CullingSnapshot snapshot = null;
            for (int index = 0; index < _cullingSnapshots.Length; index++)
            {
                if (_cullingSnapshots[index] != null && _cullingSnapshots[index].CameraId == cameraId)
                {
                    snapshot = _cullingSnapshots[index];
                    break;
                }
            }
            if (snapshot == null)
            {
                snapshot = _cullingSnapshots[_nextCullingSlot];
                if (snapshot == null)
                {
                    snapshot = new CullingSnapshot();
                    _cullingSnapshots[_nextCullingSlot] = snapshot;
                }
                _nextCullingSlot = (_nextCullingSlot + 1) % MAX_CULLING_CAMERAS;
            }
            snapshot.CameraId = cameraId;
            snapshot.Frame = Time.frameCount;
            snapshot.Sequence = ++_cullingSequence;
            snapshot.LightCount = cullingResults.visibleLights.Length;
            snapshot.InfoCount = Math.Min(perLightInfos.Length, MAX_CULLING_LIGHTS);
            snapshot.TotalSplitCount = totalSplitCount;
            snapshot.Results = cullingResults;
            for (int index = 0; index < snapshot.InfoCount; index++)
            {
                snapshot.PerLightInfos[index] = perLightInfos[index];
            }
        }

        private static void ReadCullingSnapshot(ref HDShadowRequestObservation sample, CullingResults cullingResults)
        {
            if (_cullingSnapshots == null)
            {
                return;
            }
            for (int index = 0; index < _cullingSnapshots.Length; index++)
            {
                CullingSnapshot snapshot = _cullingSnapshots[index];
                if (snapshot == null || snapshot.CameraId != sample.cameraId || snapshot.Frame != sample.frame)
                {
                    continue;
                }
                sample.cullingSnapshotFound = true;
                sample.cullingResultsMatch = snapshot.Results.Equals(cullingResults);
                sample.cullingSequence = snapshot.Sequence;
                sample.cullingCapturedFrame = snapshot.Frame;
                sample.cullingSnapshotLightCount = snapshot.LightCount;
                sample.cullingSnapshotInfoCount = snapshot.InfoCount;
                sample.cullingTotalSplitCount = snapshot.TotalSplitCount;
                if (!sample.cullingResultsMatch)
                {
                    return;
                }
                if (sample.requestLightIndex >= 0 && sample.requestLightIndex < snapshot.InfoCount)
                {
                    LightShadowCasterCullingInfo original = snapshot.PerLightInfos[sample.requestLightIndex];
                    sample.originalSplitStart = original.splitRange.start;
                    sample.originalSplitCount = original.splitRange.length;
                    sample.originalSplitExclusionMask = original.splitExclusionMask;
                    sample.originalProjectionType = (int)original.projectionType;
                    sample.originalSplitExcluded = sample.splitIndex >= 0 && sample.splitIndex < 16 && (original.splitExclusionMask & (1 << sample.splitIndex)) != 0;
                    sample.originalSplitInBuffer = sample.splitIndex >= 0 && sample.splitIndex < original.splitRange.length && original.splitRange.start >= 0 && original.splitRange.length <= snapshot.TotalSplitCount && original.splitRange.start <= snapshot.TotalSplitCount - original.splitRange.length;
                }
                if (sample.mappedLightIndex >= 0 && sample.mappedLightIndex < snapshot.InfoCount)
                {
                    LightShadowCasterCullingInfo mapped = snapshot.PerLightInfos[sample.mappedLightIndex];
                    sample.mappedSplitStart = mapped.splitRange.start;
                    sample.mappedSplitCount = mapped.splitRange.length;
                    sample.mappedSplitExclusionMask = mapped.splitExclusionMask;
                    sample.mappedProjectionType = (int)mapped.projectionType;
                    sample.mappedSplitExcluded = sample.splitIndex >= 0 && sample.splitIndex < 16 && (mapped.splitExclusionMask & (1 << sample.splitIndex)) != 0;
                    sample.mappedSplitInBuffer = sample.splitIndex >= 0 && sample.splitIndex < mapped.splitRange.length && mapped.splitRange.start >= 0 && mapped.splitRange.length <= snapshot.TotalSplitCount && mapped.splitRange.start <= snapshot.TotalSplitCount - mapped.splitRange.length;
                }
                return;
            }
        }

        internal static void Record(CullingResults cullingResults, HDShadowRequestHandle handle, in HDShadowRequest request, bool mapFound, int mappedLightIndex, string cameraId, string passName, bool isRenderingOnCache, bool willCreateRendererList)
        {
            if (!Enabled || Observed == null)
            {
                return;
            }
            int frame = Time.frameCount;
            if (frame != _frame)
            {
                _frame = frame;
                _count = 0;
            }
            if (_count++ >= MAX_OBSERVATIONS_PER_FRAME)
            {
                DroppedObservations++;
                return;
            }
            var visible = cullingResults.visibleLights;
            var database = HDLightRenderDatabase.instance;
            var packed = database.packedShadowRequestSetHandles;
            var sample = new HDShadowRequestObservation
            {
                frame = frame,
                renderedFrame = Time.renderedFrameCount,
                realtime = Time.realtimeSinceStartupAsDouble,
                cameraId = cameraId,
                passName = passName,
                requestDataIndex = request.dataIndex,
                requestLightIndex = request.lightIndex,
                mappedLightIndex = mappedLightIndex,
                cullingLightCount = visible.Length,
                splitIndex = request.cullingSplit.splitIndex,
                shadowMapType = (int)request.shadowMapType,
                requestSetIndex = handle.setHandle.relativeDataOffset,
                packedSetIndex = -1,
                expectedDataIndex = -1,
                expectedVisibleLightIndex = -1,
                currentDataEntityIndex = -1,
                mapFound = mapFound,
                isInCachedAtlas = request.isInCachedAtlas,
                shouldUseCachedShadowData = request.shouldUseCachedShadowData,
                shouldRenderCachedComponent = request.shouldRenderCachedComponent,
                isRenderingOnCache = isRenderingOnCache,
                willCreateRendererList = willCreateRendererList,
                cullingCapturedFrame = -1,
                originalSplitStart = -1,
                originalSplitCount = -1,
                originalSplitExclusionMask = -1,
                originalProjectionType = -1,
                mappedSplitStart = -1,
                mappedSplitCount = -1,
                mappedSplitExclusionMask = -1,
                mappedProjectionType = -1
            };
            if (request.dataIndex >= 0 && request.dataIndex < database.lightCount)
            {
                sample.packedSetIndex = packed[request.dataIndex].relativeDataOffset;
                sample.ownerSetMatches = sample.packedSetIndex == sample.requestSetIndex;
                sample.currentDataEntityIndex = database.lightEntities[request.dataIndex].entityIndex;
                var currentOwner = database.hdAdditionalLightData[request.dataIndex];
                if (currentOwner != null && currentOwner.legacyLight != null)
                {
                    sample.currentDataLightInstanceId = currentOwner.legacyLight.GetEntityId().ToString();
                }
            }
            Light expectedLight = null;
            for (int index = 0; index < database.lightCount; index++)
            {
                if (packed[index].relativeDataOffset != sample.requestSetIndex)
                {
                    continue;
                }
                sample.expectedDataIndex = index;
                var owner = database.hdAdditionalLightData[index];
                if (owner != null && owner.legacyLight != null)
                {
                    expectedLight = owner.legacyLight;
                    sample.expectedLightInstanceId = expectedLight.GetEntityId().ToString();
                }
                break;
            }
            for (int index = 0; index < visible.Length; index++)
            {
                Light light = visible[index].light;
                if (light != null && light == expectedLight)
                {
                    if (sample.expectedVisibleLightIndex < 0)
                    {
                        sample.expectedVisibleLightIndex = index;
                    }
                    sample.duplicateVisibleLightCount++;
                }
            }
            ReadCullingSnapshot(ref sample, cullingResults);
            if (request.lightIndex >= 0 && request.lightIndex < visible.Length)
            {
                var original = visible[request.lightIndex];
                Vector4 position = original.localToWorldMatrix.GetColumn(3);
                sample.originalPositionX = position.x;
                sample.originalPositionY = position.y;
                sample.originalPositionZ = position.z;
                if (original.light != null)
                {
                    sample.originalLightInstanceId = original.light.GetEntityId().ToString();
                }
            }
            if (mapFound && mappedLightIndex >= 0 && mappedLightIndex < visible.Length)
            {
                var mapped = visible[mappedLightIndex];
                Vector4 position = mapped.localToWorldMatrix.GetColumn(3);
                sample.mappedPositionX = position.x;
                sample.mappedPositionY = position.y;
                sample.mappedPositionZ = position.z;
                sample.culledRange = mapped.range;
                sample.culledColorR = mapped.finalColor.r;
                sample.culledColorG = mapped.finalColor.g;
                sample.culledColorB = mapped.finalColor.b;
                Light light = mapped.light;
                if (light != null)
                {
                    sample.cullingLightInstanceId = light.GetEntityId().ToString();
                    sample.mappedLightEnabled = light.isActiveAndEnabled;
                    sample.mappedLightShadows = (int)light.shadows;
                    sample.mappedLightShadowStrength = light.shadowStrength;
                    sample.mappedLightRange = light.range;
                    sample.mappedLightIntensity = light.intensity;
                }
            }
            Observed.Invoke(sample);
        }
    }
}
